class Solution:
    def maxDistance(self, position: list[int], m: int) -> int:
        position.sort()
        def canPlace(min_dist):
            count = 1
            last = position[0]
            for i in range(1, len(position)):
                if position[i] - last >= min_dist:
                    count += 1
                    last = position[i]
                    if count == m:
                        return True
            return False
        lo, hi = 1, (position[-1] - position[0]) // (m - 1)
        while lo <= hi:
            mid = (lo + hi) // 2
            if canPlace(mid):
                lo = mid + 1
            else:
                hi = mid - 1
        return hi

